#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<ll> X(N), Y(N);
    for (int i = 0; i < N; ++i) cin >> X[i];
    for (int i = 0; i < N; ++i) cin >> Y[i];

    vector<pair<ll, ll>> ptsU(N), ptsV(N);
    for (int i = 0; i < N; ++i) {
        ll u = X[i] + Y[i];
        ll v = X[i] - Y[i];
        ptsU[i] = {u, v};
        ptsV[i] = {v, u};
    }

    sort(ptsU.begin(), ptsU.end());
    sort(ptsV.begin(), ptsV.end());

    vector<ll> prefMinV(N), prefMaxV(N), suffMinV(N), suffMaxV(N);
    prefMinV[0] = prefMaxV[0] = ptsU[0].second;
    for (int i = 1; i < N; ++i) {
        prefMinV[i] = min(prefMinV[i - 1], ptsU[i].second);
        prefMaxV[i] = max(prefMaxV[i - 1], ptsU[i].second);
    }
    suffMinV[N - 1] = suffMaxV[N - 1] = ptsU[N - 1].second;
    for (int i = N - 2; i >= 0; --i) {
        suffMinV[i] = min(suffMinV[i + 1], ptsU[i].second);
        suffMaxV[i] = max(suffMaxV[i + 1], ptsU[i].second);
    }

    vector<ll> prefMinU(N), prefMaxU(N), suffMinU(N), suffMaxU(N);
    prefMinU[0] = prefMaxU[0] = ptsV[0].second;
    for (int i = 1; i < N; ++i) {
        prefMinU[i] = min(prefMinU[i - 1], ptsV[i].second);
        prefMaxU[i] = max(prefMaxU[i - 1], ptsV[i].second);
    }
    suffMinU[N - 1] = suffMaxU[N - 1] = ptsV[N - 1].second;
    for (int i = N - 2; i >= 0; --i) {
        suffMinU[i] = min(suffMinU[i + 1], ptsV[i].second);
        suffMaxU[i] = max(suffMaxU[i + 1], ptsV[i].second);
    }

    auto feasible = [&](ll D) -> bool {
        ll minU = ptsU[0].first, maxU = ptsU[N - 1].first;
        ll minV = prefMinV[N - 1], maxV = prefMaxV[N - 1];
        if (maxU - minU <= D && maxV - minV <= D) return true;

        for (int i = 0; i < N - 1; ++i) {
            ll uRangePref = ptsU[i].first - ptsU[0].first;
            if (uRangePref > D) break;
            ll vRangePref = prefMaxV[i] - prefMinV[i];
            if (vRangePref > D) continue;

            ll uRangeSuff = ptsU[N - 1].first - ptsU[i + 1].first;
            if (uRangeSuff > D) continue;
            ll vRangeSuff = suffMaxV[i + 1] - suffMinV[i + 1];
            if (vRangeSuff > D) continue;

            return true;
        }

        for (int i = 0; i < N - 1; ++i) {
            ll vRangePref = ptsV[i].first - ptsV[0].first;
            if (vRangePref > D) break;
            ll uRangePref = prefMaxU[i] - prefMinU[i];
            if (uRangePref > D) continue;

            ll vRangeSuff = ptsV[N - 1].first - ptsV[i + 1].first;
            if (vRangeSuff > D) continue;
            ll uRangeSuff = suffMaxU[i + 1] - suffMinU[i + 1];
            if (uRangeSuff > D) continue;

            return true;
        }

        return false;
    };

    ll low = 0;
    ll high = max(ptsU[N - 1].first - ptsU[0].first,
                  prefMaxV[N - 1] - prefMinV[N - 1]);

    while (low < high) {
        ll mid = (low + high) / 2;
        if (feasible(mid))
            high = mid;
        else
            low = mid + 1;
    }

    cout << low << '\n';
    return 0;
}
